#!/bin/sh
# Checks headers generated from lib/ against xxhash.h:
# - lib/xxhash_root.h, used directly as a multi-file header,
#   must preprocess exactly like xxhash.h;
# - each variant, generated by excluding some units, must preprocess exactly
#   like xxhash.h with the equivalent build macro, and must compile into
#   a library which contains only the expected symbols.

set -eu

cd "$(dirname "$0")/.."
CC=${CC:-cc}
CXX=${CXX:-c++}
NM=${NM:-nm}
tmp=tests/tmp_amalg
status=0

# name, families (comma separated), streaming, build macros (comma separated),
# C standard, expected symbol, unexpected symbols
VARIANTS="\
noxxh3        xxh32,xxh64 yes XXH_NO_XXH3                                c99 XXH64_digest XXH3_|XXH128
xxh32         xxh32       yes XXH_NO_LONG_LONG,XXH_NO_XXH3               c90 XXH32_digest XXH64|XXH3_|XXH128
xxh64         xxh64       yes XXH_NO_XXH32,XXH_NO_XXH3                   c99 XXH64_digest XXH32|XXH3_|XXH128
oneshot       xxh3        no  XXH_NO_STREAM                              c99 XXH3_128bits State|reset|update|digest
xxh32_oneshot xxh32       no  XXH_NO_LONG_LONG,XXH_NO_XXH3,XXH_NO_STREAM c90 XXH32_hashFromCanonical XXH64|XXH3_|XXH128|State|reset|update|digest
xxh64_oneshot xxh64       no  XXH_NO_XXH32,XXH_NO_XXH3,XXH_NO_STREAM     c99 XXH64_hashFromCanonical XXH32|XXH3_|XXH128|State|reset|update|digest"

# cppflags MACROS : -D options for a comma separated list of macros
cppflags() {
    echo "-D$1" | sed 's/,/ -D/g'
}

rm -rf "$tmp"
mkdir -p "$tmp"
while read -r name families streaming macros std present absent; do
    mkdir -p "$tmp/$name"
    options=""
    [ "$streaming" = yes ] || options="--no-stream"
    # shellcheck disable=SC2046,SC2086 # lists
    sh build/variant.sh $options $(echo "$families" | tr ',' ' ') > "$tmp/$name/xxhash.h"
done <<EOF
$VARIANTS
EOF

# includes the header several times, in different modes
cat > "$tmp/multi.c" <<EOF
#include XXH_HEADER
#ifndef XXH_STATIC_LINKING_ONLY
#  define XXH_STATIC_LINKING_ONLY
#endif
#include XXH_HEADER
#ifndef XXH_INLINE_ALL
#  define XXH_INLINE_ALL
#endif
#include XXH_HEADER
EOF

# preprocessors may lay out whitespace and line breaks differently,
# e.g. across file boundaries (clang -P), or where comments were removed:
# compare streams of whitespace-separated words
normalize() {
    awk '{ for (i = 1; i <= NF; i++) print $i }'
}

# compare_pp NAME REFERENCE_HEADER TESTED_HEADER COMPILER REFERENCE_CPPFLAGS CPPFLAGS...
# REFERENCE_CPPFLAGS only apply to the reference: e.g. the build macros
# of a variant, which the variant must define by itself.
compare_pp() {
    name=$1; ref=$2; new=$3; cc=$4; refflags=$5
    shift 5
    if [ "$cc" = "$CXX" ]; then lang=c++; else lang=c; fi
    for side in ref new; do
        if [ "$side" = ref ]; then header=$ref; extra=$refflags; else header=$new; extra=; fi
        # no pipe from the compiler: its failures must stop the script
        # shellcheck disable=SC2086 # extra is a list
        $cc -x $lang -E -P $extra "$@" "$header" > "$tmp/raw"
        normalize < "$tmp/raw" > "$tmp/$side.E"
        # shellcheck disable=SC2086
        $cc -x $lang -E -dM $extra "$@" "$header" > "$tmp/raw"
        sort < "$tmp/raw" > "$tmp/$side.dM"
        # shellcheck disable=SC2086
        $cc -x $lang -E -P $extra "$@" -DXXH_HEADER="\"$PWD/$header\"" "$tmp/multi.c" > "$tmp/raw"
        normalize < "$tmp/raw" > "$tmp/$side.multi"
    done
    for mode in E dM multi; do
        if ! cmp -s "$tmp/ref.$mode" "$tmp/new.$mode"; then
            echo "FAIL: $name ($cc $*): $mode output differs from $ref" >&2
            status=1
        fi
    done
}

# note: XXH_IMPLEMENTATION is defined empty, as xxhash.h redefines it in INLINE_ALL mode
for flags in \
    "" \
    "-DXXH_STATIC_LINKING_ONLY" \
    "-DXXH_STATIC_LINKING_ONLY -DXXH_IMPLEMENTATION=" \
    "-DXXH_INLINE_ALL" \
    "-DXXH_PRIVATE_API" \
    "-DXXH_NAMESPACE=NS_ -DXXH_STATIC_LINKING_ONLY -DXXH_IMPLEMENTATION=" \
    "-DXXH_NO_STREAM -DXXH_INLINE_ALL" \
    "-DXXH_NO_LONG_LONG -DXXH_INLINE_ALL"
do
    # shellcheck disable=SC2086 # flags are meant to be split
    compare_pp root xxhash.h lib/xxhash_root.h "$CC" "" $flags
    while read -r name families streaming macros std present absent; do
        # shellcheck disable=SC2086
        compare_pp "$name" xxhash.h "$tmp/$name/xxhash.h" "$CC" "$(cppflags "$macros")" $flags
    done <<EOF
$VARIANTS
EOF
done
compare_pp root xxhash.h lib/xxhash_root.h "$CXX" "" -DXXH_INLINE_ALL
while read -r name families streaming macros std present absent; do
    compare_pp "$name" xxhash.h "$tmp/$name/xxhash.h" "$CXX" "$(cppflags "$macros")" -DXXH_INLINE_ALL
done <<EOF
$VARIANTS
EOF

# excluding XXH3 units must be identical to removing XXH_NO_XXH3 sections from xxhash.h
# (modulo consecutive empty lines, which the generator merges)
squeeze() {
    awk 'NF || !blank { print } { blank = !NF }' "$1"
}
if command -v unifdef >/dev/null 2>&1; then
    unifdef -DXXH_NO_XXH3 xxhash.h > "$tmp/raw" || [ $? -eq 1 ]
    squeeze "$tmp/raw" > "$tmp/unifdef.h"
    sh build/amalgamate.sh -x xxh3_api.h -x xxh3_stream_api.h -x xxh3_static.h -x xxh3_stream_static.h \
        -x xxh3_impl.h lib/xxhash_root.h > "$tmp/raw"
    squeeze "$tmp/raw" > "$tmp/noxxh3.h"
    if ! cmp -s "$tmp/unifdef.h" "$tmp/noxxh3.h"; then
        echo "FAIL: excluding XXH3 units differs from: unifdef -DXXH_NO_XXH3 xxhash.h" >&2
        status=1
    fi
else
    echo "note: unifdef not found, skipping unifdef comparison"
fi

# each variant must compile cleanly, without build macro, and contain only the expected symbols
while read -r name families streaming macros std present absent; do
    cp xxhash.c "$tmp/$name/"
    $CC -std="$std" -pedantic -Wall -Wextra -Werror -c "$tmp/$name/xxhash.c" -o "$tmp/$name/xxhash.o"
    $NM "$tmp/$name/xxhash.o" > "$tmp/$name/symbols"
    if grep -E -q "$absent" "$tmp/$name/symbols"; then
        echo "FAIL: $name variant defines unexpected symbols ($absent)" >&2
        status=1
    fi
    if ! grep -q "$present" "$tmp/$name/symbols"; then
        echo "FAIL: $name variant lacks $present" >&2
        status=1
    fi
done <<EOF
$VARIANTS
EOF

# the generators must work from a directory whose path contains spaces
spaced="$PWD/$tmp/dir with spaces"
mkdir -p "$spaced"
cp -R lib build "$spaced/"
if ! sh "$spaced/build/amalgamate.sh" --check xxhash.h "$spaced/lib/xxhash_root.h" \
   || ! sh "$spaced/build/variant.sh" xxh32 | cmp -s - "$tmp/xxh32/xxhash.h"; then
    echo "FAIL: generation from a path containing spaces" >&2
    status=1
fi

# removing comments must keep the code intact: synthetic units, with comments
# in difficult places, must preprocess alike in every comment mode
syn="$tmp/synthetic"
mkdir -p "$syn/lib" "$syn/out"
license='/*
 * Copyright (C) Yann Collet
 * BSD 2-Clause License
 */
'
{ echo "$license"; printf '#include "t_api.h"\n#include "t_impl.h"\n'; } > "$syn/lib/xxhash_root.h"
{ echo "$license"; cat <<'EOF'
/*!
 * documentation block, followed by code and by another comment on its last line
 */ int a; /* comment */ int b;

/*! @brief documented declaration */
int f(void); /*!< documentation of a member */
EOF
} > "$syn/lib/t_api.h"
{ echo "$license"; cat <<'EOF'
#define X1 1 /* comment spanning lines,
   inside a directive */ + 2
#define X2 3 /* comment ending with a backslash \
   inside a directive */ + 4
#define X3(a) \
   (a) /* comment spanning lines,
   inside a continued macro */ + \
   5
#define X4 6 \
   /* comment-only continuation line,
   followed by code */ + 7
#define X5 8  /* comment spanning lines,
                 followed by nothing */
int g(void) { return X1 + X2 + X3(0) + X4 + X5; }
const char* s = "/* not a comment */"; const char c = '/'; int/**/d;
int h(int x) { int y = 1 /* comment spanning lines,
    within code */ + 2;
    switch (x) {
    case 0: x++;  /* fallthrough */
    case 1: x++;  /* FALLTHRU */
    default: break;
    }
    return x + y;
}
EOF
} > "$syn/lib/t_impl.h"
for comments in all api none; do
    sh build/amalgamate.sh --comments "$comments" "$syn/lib/xxhash_root.h" > "$syn/out/$comments.h"
done
for comments in api none; do
    compare_pp "synthetic units, --comments $comments" "$syn/out/all.h" "$syn/out/$comments.h" "$CC" ""
    if [ "$(grep -c -i -e 'fallthrough \*/' -e 'fallthru \*/' "$syn/out/$comments.h")" -ne 2 ]; then
        echo "FAIL: synthetic units, --comments $comments: fallthrough markers removed" >&2
        status=1
    fi
done

if [ "$status" -eq 0 ]; then
    rm -rf "$tmp"
    echo "amalgamation variants: OK"
fi
exit "$status"
